import { PlaneGeometry, Mesh, Group, Vector3, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { parallaxScroll } from '@/primitives';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const group = new Group();

  // Parse config
  const position = new Vector3(0, 1, 0.06);
  const rotation = new Vector3(0, 0, 0);
  const scale = new Vector3(1, 1, 1);

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Get text items
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(item => item.role === 'headline') || { text: 'Journal 2', role: 'headline', typography: { fontSize: 39 } };

  // Create card plane
  const cardGeometry = new PlaneGeometry(1.8, 1.2);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: new Color(colors.paper),
    transparent: true,
    opacity: 0.9,
    roughness: 0.6,
    metalness: 0.2
  });

  const cardMesh = new Mesh(cardGeometry, cardMaterial);
  cardMesh.position.set(0, 0, 0);
  cardMesh.rotation.set(0, 0, 0);
  group.add(cardMesh);

  // Load texture if imageUrl exists
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      cardMaterial.map = tex;
      cardMaterial.needsUpdate = true;
    });
  }

  // Create headline text
  const headlineText = ctx.fontAtlas.createText(
    headlineItem.text || 'Journal 2',
    {
      fontSize: 0.34, // scene-unit em height for headline
      color: colors.ink,
      align: 'left',
      maxWidthPx: 400,
      letterSpacingPx: 0.02
    }
  );

  if (headlineText) {
    headlineText.position.set(-0.7, 0.3, 0.01);
    headlineText.scale.set(0.01, 0.01, 0.01);
    group.add(headlineText);
  }

  // Apply scene placement
  group.position.copy(position);
  group.rotation.set(rotation.x, rotation.y, rotation.z);
  group.scale.copy(scale);

  // Event handlers
  group.userData.handlers = {
    hover: () => {
      gsap.to(group.position, {
        y: 1.15,
        duration: 0.3,
        ease: 'power3.out'
      });
    },
    hoverOut: () => {
      gsap.to(group.position, {
        y: 1.0,
        duration: 0.3,
        ease: 'power3.out'
      });
    },
    click: () => {
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
        onComplete: () => {
          gsap.to(group.scale, {
            x: 1.0,
            y: 1.0,
            duration: 0.3,
            ease: 'power3.out'
          });
        }
      });
      ctx.emit('hub-journal.select', { cardId: 'journal-card-2' });
    }
  };

  // Cinematic primitives - parallax-scroll
  const primitives = config.cinematicPrimitives || [];
  const parallaxPrimitive = primitives.find(p => p.name === 'parallax-scroll');

  let parallaxResult = null;
  if (parallaxPrimitive) {
    parallaxResult = ctx.primitives['parallax-scroll'](group, {
      intensity: parallaxPrimitive.params?.intensity || 0.25
    });
  }

  // Entrance animation
  gsap.from(group.position, {
    y: 1.4,
    duration: 0.7,
    ease: 'power3.out',
    delay: 0.4
  });

  gsap.from(cardMaterial, {
    opacity: 0,
    duration: 0.5,
    ease: 'power2.out',
    delay: 0.4
  });

  if (headlineText) {
    gsap.from(headlineText.position, {
      y: 0.5,
      duration: 0.5,
      ease: 'power2.out',
      delay: 0.5
    });
  }

  // Cleanup
  group.userData.cleanup = () => {
    if (parallaxResult && parallaxResult.cleanup) {
      parallaxResult.cleanup();
    }

    if (parallaxResult && parallaxResult.timeline) {
      parallaxResult.timeline.kill();
    }

    // Kill all GSAP timelines on this group
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(cardMaterial);
    if (headlineText) {
      gsap.killTweensOf(headlineText.position);
    }

    // Dispose geometry and material
    cardGeometry.dispose();
    cardMaterial.dispose();

    // Remove all children
    while (group.children.length > 0) {
      const child = group.children[0];
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
      group.remove(child);
    }

    // Nullify handlers
    group.userData.handlers = {};
  };

  return group;
}
